const icons={layout:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',car:'<path d="m5 17-1 3m15-3 1 3M3 11l2-6h14l2 6v6H3zM3 11h18M6 14h2m8 0h2"/>',plus:'<path d="M12 5v14M5 12h14"/>',orders:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 9h6m-6 4h6m-6 4h3"/>',wallet:'<path d="M20 8V5H4a2 2 0 0 1 0-4h14v4M4 5v15h17V8h-7v7h7m-4-4h.01"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m3 11v-3a6 6 0 0 0-2-4"/>',drop:'<path d="M12 2s-7 8-7 13a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/><path d="M8 15a4 4 0 0 0 4 4"/>',box:'<path d="m3 7 9-5 9 5v10l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v10M7 4l10 6"/>',money:'<path d="M12 2v20m5-16H9a4 4 0 0 0 0 8h6a4 4 0 0 1 0 8H6"/>',chart:'<path d="M3 3v18h18M7 16v-4m5 4V7m5 9V4"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-9 12h6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3 1-2h4l1 2 3 2 3 1v4l-2 2 2 2v4l-3 1-3 2-1 2h-4l-1-2-3-2-3-1v-4l2-2-2-2V6l3-1Z"/>',backup:'<path d="M4 14a8 8 0 1 1 3 5M4 4v6h6M12 7v5l3 2"/>',book:'<path d="M12 5C7 2 3 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-4-2-7-1-10 1Zm0 0v16"/>',rocket:'<path d="M12 16 8 12c0-5 7-9 13-9 0 6-4 13-9 13ZM8 8H4l-3 5 7-1m8 4v4l-5 3 1-7M5 16l-3 6 6-3"/><circle cx="16" cy="8" r="1"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',alert:'<path d="m12 3 10 18H2L12 3Zm0 5v5m0 4h.01"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',panel:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M9 3v18m4-13h4m-4 4h4"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4Zm-4 10 3 3 5-6"/>',refresh:'<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"/><path d="M3 21v-5h5"/>'};
const lucideNames={layout:'LayoutDashboard',car:'Car',plus:'Plus',orders:'ClipboardList',wallet:'Wallet',users:'Users',drop:'Droplets',box:'Package',money:'DollarSign',chart:'ChartNoAxesCombined',bell:'Bell',settings:'Settings',backup:'DatabaseBackup',book:'BookOpen',rocket:'Rocket',search:'Search',clock:'Clock3',arrow:'ArrowRight',check:'Check',more:'Ellipsis',menu:'Menu',filter:'SlidersHorizontal',sun:'Sun',download:'Download',close:'X',alert:'TriangleAlert',user:'UserRound',calendar:'CalendarDays',panel:'PanelLeft',shield:'ShieldCheck',refresh:'RefreshCw'};
const icon=(n)=>{const nodes=window.lucide?.icons[lucideNames[n]];const contents=nodes?nodes.map(([tag,attrs])=>`<${tag} ${Object.entries(attrs).map(([k,v])=>`${k}="${v}"`).join(' ')}/>`).join(''):icons[n]||icons.layout;return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${contents}</svg>`};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const today=()=>new Date().toLocaleDateString('pt-BR');const stamp=()=>new Date().toISOString();const uid=()=>Date.now()+Math.floor(Math.random()*1000);
const stages=['Aguardando','Em lavagem','Em acabamento','Pronto','Entregue'];
const nav=[['Visão geral',[['dashboard','Dashboard','layout']]],['Operacional',[['patio','Pátio e Fila','car'],['nova','Nova Ordem de Serviço','plus'],['ordens','Ordens de Serviço','orders'],['caixa','Caixa','wallet'],['agenda_online','Agenda Online','calendar']]],['Cadastros',[['clientes','Clientes e Veículos','users'],['servicos','Serviços e Combos','drop'],['estoque','Produtos e Estoque','box'],['equipe','Equipe','users']]],['Gestão',[['financeiro','Financeiro','money'],['comissoes','Comissões','chart'],['relatorios','Relatórios','chart']]],['Sistema',[['notificacoes','Notificações','bell'],['config','Configurações','settings'],['backup','Backup e Restauração','backup'],['manual','Manual de Uso','book']]]];
const fresh=()=>({version:1,settings:{name:'Minha unidade',phone:'',document:'',address:'',hours:'',tolerance:15,next:1001,theme:'dark',payments:'Dinheiro, PIX, Débito, Crédito',currency:'BRL',print:'A4',saasLicenseKey:'',saasSlug:''},clients:[],services:[],team:[],products:[],orders:[],movements:[],stockHistory:[],cash:{open:false,initial:0,opened:null},cashHistory:[],backup:null,license:null});
let state = fresh();
function persist(){try{localStorage.setItem('lava-app-v1',JSON.stringify(state))}catch{toast('Não foi possível salvar. Gere um backup para preservar os dados.')}}
let page=location.hash.slice(1)||'patio',query='',stageFilter=0,view='board',draft={},wizardStep=1,periodFrom='',periodTo='';
const $=s=>document.querySelector(s);const elapsed=o=>Math.max(0,Math.floor(((o.delivered?new Date(o.delivered):Date.now())-new Date(o.entered))/60000));const late=o=>o.stage<3&&elapsed(o)>o.duration+Number(state.settings.tolerance);const currentOrders=()=>state.orders.filter(o=>new Date(o.entered).toLocaleDateString('pt-BR')===today());const revenues=()=>state.movements.filter(m=>m.value>0).reduce((s,m)=>s+m.value,0);const balance=()=>Number(state.cash.initial)+state.movements.filter(m=>!state.cash.opened||m.date>=state.cash.opened).reduce((s,m)=>s+m.value,0);const initials=n=>(n||'').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('')||'--';const matches=o=>[o.plate,o.client,o.service,o.id].join(' ').toLowerCase().includes(query.toLowerCase());
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function route(id){location.hash=id;if(page===id)render()}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'patio';query='';render();window.scrollTo(0,0)});
function shell(){document.body.classList.toggle('light',state.settings.theme==='light');$('#sidebar').innerHTML=`<a class="brand" href="#patio"><span class="brand-mark">${icon('drop')}</span><div class="brand-text"><strong>Gestão Lava-Rápido</strong><small>CONTROLE DA OPERAÇÃO</small></div></a><div class="nav-scroll">${nav.map(([g,items])=>`<div class="group">${g}</div>${items.map(([id,title,ic])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span class="nav-text">${title}</span>${id==='patio'?`<span class="count">${state.orders.filter(o=>o.stage<4).length}</span>`:''}</a>`).join('')}`).join('')}</div><div class="sidebar-foot"><div class="local"><span class="dot"></span> Dados neste dispositivo <span style="margin-left:auto">${icon('shield')}</span></div><div class="profile"><span class="avatar">AB</span><div><strong>${esc(state.settings.name)}</strong><small>Administrador · Unidade principal</small></div></div></div>`;
$('#header').innerHTML=`<div class="header-left"><button class="icon-button" onclick="document.body.classList.toggle('collapse')" aria-label="Recolher menu">${icon('panel')}</button><span class="crumb">Operação <span style="margin:0 10px">/</span></span><b>${esc(nav.flatMap(x=>x[1]).find(x=>x[0]===page)?.[1]||'Mais opções')}</b></div><div class="header-right"><span class="date-label">${icon('calendar')}${new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'})}</span><small><span class="dot"></span> Armazenamento local</small><button class="icon-button" onclick="toggleTheme()" aria-label="Alternar tema">${icon('sun')}</button><button class="icon-button" onclick="route('notificacoes')" aria-label="Notificações">${icon('bell')}</button><span class="avatar">AB</span></div>`;
$('#mobile').innerHTML=[['patio','Pátio','car'],['nova','Nova OS','plus'],['clientes','Clientes','users'],['caixa','Caixa','wallet'],['mais','Mais','menu']].map(([id,t,ic])=>`<a href="#${id}" class="${page===id?'active':''} ${id==='nova'?'new-os':''}">${icon(ic)}${t}</a>`).join('')}
function toggleTheme(){state.settings.theme=state.settings.theme==='dark'?'light':'dark';persist();render()}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function btn(text,action,ic='plus',primary=false,cls=''){return `<button class="${primary?'primary':''} ${cls}" onclick="${action}">${icon(ic)}${text}</button>`}
function stat(label,value,foot,ic){return `<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function search(placeholder='Buscar por placa, cliente ou OS…'){return `<div class="search">${icon('search')}<input id="search" aria-label="Buscar" placeholder="${placeholder}" value="${esc(query)}" oninput="query=this.value;refreshResults()"><kbd>/</kbd></div>`}
function badge(text,cls=''){return `<span class="badge ${cls}">${text}</span>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}"><div class="empty">Nenhum resultado encontrado.</div></td></tr>`}</tbody></table></div>`}
function render(){shell();const screens={patio:patio,dashboard:dashboard,nova:newOrder,ordens:ordersPage,caixa:cashPage,agenda_online:onlineAgendaPage,clientes:clientsPage,servicos:servicesPage,estoque:stockPage,equipe:teamPage,financeiro:financePage,comissoes:commissionsPage,relatorios:reportsPage,notificacoes:notificationsPage,config:settingsPage,backup:backupPage,manual:manualPage,evolucao:evolutionPage,licenca:licensePage,mais:morePage};$('#main').innerHTML=(!navigator.onLine?'<div id="offline-banner">Sem internet. Os dados e as operações continuam neste dispositivo.</div>':'')+(screens[page]||patio)()}
function refreshResults(){let pos=$('#search')?.selectionStart;const target=$('#results');if(target){target.innerHTML=page==='patio'?board():page==='ordens'?ordersTable():page==='clientes'?clientsTable():''}else render();$('#search')?.focus();if(pos!=null)$('#search')?.setSelectionRange(pos,pos)}
function vehicle(o){return `<article class="vehicle ${late(o)?'late':''}"><div class="card-top"><span class="plate">${esc(o.plate)}</span><span class="order-id">#${o.id}</span></div><div class="vehicle-model">${esc(o.brand)} ${esc(o.model)} · ${esc(o.color)}</div><div class="customer">${icon('user')}${esc(o.client)}</div><div class="service">${esc(o.service)}</div><div class="time-row">${icon('clock')}${new Date(o.entered).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}<span class="elapsed">${late(o)?'Atrasado · ':''}${elapsed(o)} min</span></div>${o.note?`<div class="note">${icon('alert')}${esc(o.note)}</div>`:''}<div class="card-bottom"><span class="employee"><span class="avatar">${initials(o.employee)}</span>${esc((o.employee||'').split(' ')[0]||'--')}</span><span class="price">${money(o.total)}</span></div><div class="card-buttons">${o.stage<4?btn(o.stage===3?'Entregar':'Avançar etapa',`advance(${o.id})`,o.stage===3?'check':'arrow',o.stage===0):`<span class="badge good">${icon('check')} Entregue</span>`}<button class="detail" aria-label="Detalhes da OS ${o.id}" onclick="orderDetail(${o.id})">${icon('more')}</button></div></article>`}
function board(){return `<div class="board ${view==='list'?'list-board':''}">${stages.map((s,i)=>{let os=currentOrders().filter(o=>o.stage===i&&matches(o));return `<section class="column ${stageFilter===i?'show':''}"><div class="column-head"><span class="stage-dot s${i}"></span>${s}<span class="qty">${os.length}</span></div>${os.map(vehicle).join('')||'<div class="empty-col">Nenhum veículo nesta etapa.</div>'}</section>`}).join('')}</div>`}
function patio(){const os=currentOrders();return head('Pátio e Fila','Acompanhe cada veículo, da chegada à entrega.',`<span class="date-label">${icon('clock')} Operação de hoje</span>${btn('Nova OS',"startOrder()",'plus',true)}`)+`<div class="stats">${stat('No pátio',os.filter(o=>o.stage<4).length,'Veículos em operação','car')}${stat('Em atendimento',os.filter(o=>[1,2].includes(o.stage)).length,'Lavagem e acabamento','drop')}${stat('Prontos para entrega',os.filter(o=>o.stage===3).length,'Aguardando retirada','check')}${stat('Concluídos hoje',os.filter(o=>o.stage===4).length,'<b>Operação do dia</b>','orders')}</div><div class="toolbar">${search()}<div class="toolbar-right"><span class="date-label">${icon('calendar')}Hoje, ${today()}</span><div class="view-switch"><button class="${view==='board'?'selected':''}" onclick="view='board';render()">${icon('layout')}Quadro</button><button class="${view==='list'?'selected':''}" onclick="view='list';render()">${icon('menu')}Lista</button></div>${btn('Filtrar',"filterModal()",'filter')}</div></div><div class="mobile-stages">${stages.map((s,i)=>`<button class="${stageFilter===i?'active':''}" onclick="stageFilter=${i};render()">${s} <span>${os.filter(o=>o.stage===i).length}</span></button>`).join('')}</div><div id="results">${board()}</div><div class="board-footer"><span>${os.length} veículos hoje · ${os.filter(o=>o.stage<4).length} no pátio</span><span class="legend"><i></i>Borda âmbar indica atraso na previsão</span><span>Atualizado neste dispositivo</span></div>`}
function modal(title,body){$('#dialog').setAttribute('aria-labelledby','dialog-title');$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" onclick="closeModal()" aria-label="Fechar">${icon('close')}</button></div>${body}`;if(!$('#dialog').open)$('#dialog').showModal()}
function closeModal(){$('#dialog').close()}
function confirmAction(title,text,action){modal(title,`<p>${text}</p><div class="form-actions">${btn('Cancelar','closeModal()','close')}${btn('Confirmar',action,'check',true)}</div>`)}
function filterModal(){modal('Filtrar pátio',`<p class="muted">Selecione a etapa. No computador, a busca refina todas as colunas.</p><div class="tabs" style="flex-wrap:wrap">${stages.map((s,i)=>btn(s,`stageFilter=${i};closeModal();render()`,'car')).join('')}</div>`)}
function advance(id){const o=state.orders.find(o=>o.id===id);if(o.stage===3&&!o.paid){receiveModal(id);return}if(o.stage===3){confirmAction('Confirmar entrega',`Entregar o veículo ${esc(o.plate)} para ${esc(o.client)}?`,`finishDelivery(${id})`);return}o.stage++;persist();render();toast(`${o.plate} → ${stages[o.stage]}`)}
function finishDelivery(id){const o=state.orders.find(o=>o.id===id);o.stage=4;o.delivered=stamp();persist();closeModal();render();toast('Entrega registrada no histórico do veículo.')}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);modal(`Ordem de serviço #${id}`,`<div class="intro-row"><span class="avatar">${icon('car')}</span><div><h2 style="margin:0">${esc(o.plate)}</h2><p class="muted" style="margin:4px 0">${esc(o.brand)} ${esc(o.model)} · ${esc(o.color)}</p></div>${badge(stages[o.stage],o.stage===4?'good':'info')}</div>${[['Cliente',o.client],['Telefone',o.phone],['Serviço',o.service],['Adicionais',(o.extras||[]).join(', ')||'Nenhum'],['Responsável',o.employee],['Entrada',new Date(o.entered).toLocaleString('pt-BR')],['Previsão',new Date(new Date(o.entered).getTime()+o.duration*60000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})],['Pagamento',o.paid?`Recebido · ${o.method}`:'Pendente'],['Observações / avarias',o.note||'Nenhuma registrada']].map(([a,b])=>`<div class="summary-line"><small>${a}</small><span>${esc(b)}</span></div>`).join('')}<div class="summary-line total"><span>Total</span><span>${money(o.total)}</span></div><div class="form-actions">${btn('Imprimir','window.print()','orders')}${!o.paid?btn('Receber pagamento',`receiveModal(${id})`,'wallet',true):''}${o.stage<4?btn('Avançar etapa',`closeModal();advance(${id})`,'arrow'):''}</div>`)}
function dashboard(){const os=currentOrders(),paid=os.filter(o=>o.paid),sum=paid.reduce((s,o)=>s+o.total,0);return head('Dashboard','Uma visão objetiva da operação de hoje.',btn('Nova OS','startOrder()','plus',true))+`<div class="stats">${stat('Faturamento do dia',money(sum),`${paid.length} ordens recebidas`,'money')}${stat('Ticket médio',money(paid.length?sum/paid.length:0),'Por ordem recebida','chart')}${stat('Tempo médio',`${Math.round(os.filter(o=>o.stage===4).reduce((s,o)=>s+elapsed(o),0)/(os.filter(o=>o.stage===4).length||1))} min`,'Veículos entregues hoje','clock')}${stat('Caixa',state.cash.open?'Aberto':'Fechado',state.cash.open?`Saldo: ${money(balance())}`:'Abra para registrar recebimentos','wallet')}</div><div class="two-grid"><div><section class="panel"><h2>Operação atual do pátio</h2>${stages.map((s,i)=>`<div class="activity"><span><span class="stage-dot s${i}" style="display:inline-block;margin-right:8px"></span>${s}</span><b>${os.filter(o=>o.stage===i).length} veículos</b></div>`).join('')}<div class="form-actions">${btn('Abrir pátio',"route('patio')",'arrow')}</div></section><section class="panel"><h2>Últimas movimentações</h2>${movementTable(state.movements.slice(-5).reverse())}</section></div><div><section class="panel"><h2>Ordens atrasadas ${badge(os.filter(late).length,'warn')}</h2>${os.filter(late).map(o=>`<div class="activity"><div><b>${o.plate}</b><p class="muted" style="margin:4px 0">${esc(o.client)} · ${elapsed(o)} min</p></div>${btn('Detalhes',`orderDetail(${o.id})`,'arrow')}</div>`).join('')||'<p class="muted">Nenhuma ordem atrasada.</p>'}</section><section class="panel"><h2>Serviços mais vendidos</h2>${serviceTotals().slice(0,3).map(([s,n])=>`<div style="display:flex;justify-content:space-between"><span>${esc(s)}</span><b>${n}</b></div><div class="bar"><span style="width:${n/Math.max(...serviceTotals().map(x=>x[1]))*100}%"></span></div>`).join('')}</section><section class="panel"><h2>Estoque baixo</h2>${state.products.filter(p=>p.qty<=p.min).map(p=>`<div class="activity"><span>${esc(p.name)}</span>${badge(`${p.qty} ${p.unit}`,'warn')}</div>`).join('')||'<p>Estoque regular.</p>'}</section><section class="panel"><h2>Equipe hoje</h2>${state.team.map(e=>`<div class="activity"><span>${esc(e.name)}</span><b>${os.filter(o=>o.employee===e.name).length} OS</b></div>`).join('')}</section></div></div>`}
function startOrder(preserveDraft=false){if(!preserveDraft)draft={};wizardStep=1;route('nova')}
function field(label,name,value='',type='text',extra=''){return `<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,options,value=''){return `<div><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function newOrder(){return head('Nova Ordem de Serviço','Atendimento rápido, com todas as informações em um só lugar.')+`<div class="steps">${['Cliente e veículo','Serviços','Conferência'].map((x,i)=>`<div class="step ${wizardStep===i+1?'active':''}"><span>${i+1}</span>${x}</div>`).join('')}</div><div class="two-grid"><div class="panel"><form id="os-form" onsubmit="orderNext(event)">${wizardStep===1?`<h2>Cliente e veículo</h2><label for="client-search">Localizar cliente ou veículo</label><div class="search" style="max-width:none;margin-bottom:12px">${icon('search')}<input id="client-search" placeholder="Nome, telefone ou placa" oninput="findClient(this.value)"></div><div id="client-found"></div><div class="form-grid">${field('Nome do cliente *','client',draft.client||'','text','required')}${field('Telefone *','phone',draft.phone||'','tel','required')}${field('Placa *','plate',draft.plate||'','text','required pattern="[A-Za-z]{3}[0-9][A-Za-z0-9][0-9]{2}" maxlength="7" placeholder="ABC1D23" style="text-transform:uppercase"')}${field('Modelo *','model',draft.model||'','text','required')}${field('Marca *','brand',draft.brand||'','text','required')}${field('Cor *','color',draft.color||'','text','required')}${field('Ano','year',draft.year||'','number','min="1950" max="2030"')}</div>`:wizardStep===2?`<h2>Serviços e atendimento</h2><div class="form-grid">${selectField('Serviço principal *','service',state.services.filter(s=>s.active&&s.category!=='Adicional').map(s=>[s.id,`${s.name} · ${money(s.price)}`]),draft.service||2)}${selectField('Funcionário responsável','employee',state.team.filter(t=>t.active).map(e=>[e.name,e.name]),draft.employee)}${field('Desconto autorizado (R$)','discount',draft.discount||0,'number','min="0" step="0.01"')}${selectField('Pagamento antecipado','prepay',[['','Receber posteriormente'],...['Dinheiro','PIX','Débito','Crédito','Outros'].map(x=>[x,x])],draft.prepay)}</div><h3 style="margin:20px 0 12px">Serviços adicionais</h3>${state.services.filter(s=>s.active&&s.category==='Adicional').map(s=>`<label class="option"><input type="checkbox" name="extras" value="${s.id}" ${(draft.extras||[]).includes(String(s.id))?'checked':''}>${esc(s.name)}<b>${money(s.price)}</b></label>`).join('')}<label for="note" style="margin-top:20px">Observações e avarias aparentes</label><textarea id="note" name="note" placeholder="Ex.: risco na porta direita, cuidado com objetos no porta-malas">${esc(draft.note||'')}</textarea>`:`<h2>Confira antes de confirmar</h2>${orderSummary()}<div class="notice">${icon('shield')}Ao confirmar, o veículo entrará na etapa Aguardando. ${draft.prepay?'O recebimento será registrado manualmente no caixa.':''}</div><p id="os-error" class="error"></p>`}<div class="form-actions">${wizardStep>1?btn('Voltar','orderBack()','arrow'):btn('Cancelar',"route('patio')",'close')}<button class="primary" type="submit">${wizardStep===3?'Confirmar entrada no pátio':'Continuar'}${icon(wizardStep===3?'check':'arrow')}</button></div></form></div><div><section class="panel"><div class="section-caption">Resumo do atendimento</div><h2>${draft.plate?esc(draft.plate):'Nova entrada no pátio'}</h2><p class="muted">${draft.client?esc(draft.client):'Preencha os dados do cliente e do veículo para iniciar a ordem.'}</p>${wizardStep>1?`<div class="summary-line"><span>Veículo</span><b>${esc(draft.brand)} ${esc(draft.model)}</b></div>`:''}<div class="summary-line"><span>Etapa inicial</span>${badge('Aguardando','info')}</div><div class="notice">Os dados são armazenados somente neste navegador. Mantenha seus backups em local seguro.</div></section></div></div>`}
function saveDraft(){const f=$('#os-form');if(!f)return;const fd=new FormData(f);for(const [k,v] of fd)if(k!=='extras')draft[k]=v;if(wizardStep===2)draft.extras=fd.getAll('extras')}
function orderBack(){saveDraft();wizardStep--;render()}
function orderNext(e){e.preventDefault();saveDraft();if(wizardStep<3){if(wizardStep===2&&draftTotal()<0){toast('O desconto não pode superar o valor dos serviços.');return}wizardStep++;render();return}if(draft.prepay&&!state.cash.open){$('#os-error').textContent='Abra o caixa antes de registrar pagamento antecipado. Ou volte e selecione Receber posteriormente.';return}const s=state.services.find(s=>s.id===Number(draft.service)),extra=state.services.filter(s=>(draft.extras||[]).includes(String(s.id)));let c=state.clients.find(c=>c.id===draft.clientId);const v={plate:draft.plate.toUpperCase(),brand:draft.brand,model:draft.model,color:draft.color,year:draft.year,notes:draft.note||''};if(!c){c={id:uid(),name:draft.client,phone:draft.phone,notes:'',vehicles:[v]};state.clients.push(c)}else if(!c.vehicles.some(x=>x.plate===v.plate))c.vehicles.push(v);const o={id:Number(state.settings.next++),clientId:c.id,client:draft.client,phone:draft.phone,...v,service:s.name,extras:extra.map(x=>x.name),total:draftTotal(),duration:s.duration+extra.reduce((n,x)=>n+x.duration,0),employee:draft.employee,stage:0,entered:stamp(),paid:!!draft.prepay,paidAt:draft.prepay?stamp():null,method:draft.prepay,note:draft.note,discount:Number(draft.discount)};state.orders.push(o);if(draft.prepay)state.movements.push({id:uid(),date:stamp(),type:'Recebimento',description:`OS #${o.id} · ${o.client}`,value:o.total,method:o.method,orderId:o.id});persist();draft={};wizardStep=1;route('patio');toast(`OS #${o.id} criada. Veículo na fila.`)}
function draftTotal(){const s=state.services.find(s=>s.id===Number(draft.service));return (s?.price||0)+state.services.filter(s=>(draft.extras||[]).includes(String(s.id))).reduce((n,s)=>n+s.price,0)-Number(draft.discount||0)}
function orderSummary(){const s=state.services.find(s=>s.id===Number(draft.service));return [['Cliente',draft.client],['Telefone',draft.phone],['Veículo',`${draft.plate?.toUpperCase()} · ${draft.brand} ${draft.model} · ${draft.color}`],['Serviço',s?.name],['Adicionais',state.services.filter(s=>(draft.extras||[]).includes(String(s.id))).map(s=>s.name).join(', ')||'Nenhum'],['Responsável',draft.employee],['Desconto',money(draft.discount)],['Previsão',new Date(Date.now()+((s?.duration||0)+state.services.filter(s=>(draft.extras||[]).includes(String(s.id))).reduce((n,s)=>n+s.duration,0))*60000).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})],['Observações',draft.note||'Nenhuma'],['Pagamento',draft.prepay||'Na retirada']].map(([k,v])=>`<div class="summary-line"><small>${k}</small><span>${esc(v)}</span></div>`).join('')+`<div class="summary-line total"><span>Total</span><span>${money(draftTotal())}</span></div>`}
function findClient(q){$('#client-found').innerHTML=q?state.clients.filter(c=>JSON.stringify(c).toLowerCase().includes(q.toLowerCase())).map(c=>`<div style="margin-bottom:8px">${c.vehicles.map((v,i)=>btn(`${esc(c.name)} · ${v.plate}`,`pickClient(${c.id},${i})`,'car')).join('')}</div>`).join('')||'<p class="muted">Cliente não encontrado. Cadastre nos campos abaixo.</p>':''}
function pickClient(id,i){const c=state.clients.find(c=>c.id===id);draft={...draft,clientId:id,client:c.name,phone:c.phone,...c.vehicles[i]};render()}
function ordersPage(){return head('Ordens de Serviço','Consulte o histórico e acompanhe os atendimentos.',btn('Nova OS','startOrder()','plus',true))+`<div class="toolbar">${search()}</div><div class="panel" id="results">${ordersTable()}</div>`}
function ordersTable(){return table(['OS / Placa','Cliente','Serviço','Etapa','Pagamento','Total',''],state.orders.filter(matches).slice().reverse().map(o=>[`<b>#${o.id} · ${esc(o.plate)}</b>`,esc(o.client),esc(o.service),badge(stages[o.stage],o.stage===4?'good':'info'),badge(o.paid?'Recebido':'Pendente',o.paid?'good':'warn'),money(o.total),btn('Detalhes',`orderDetail(${o.id})`,'arrow')]))}
function movementTable(m){return table(['Data','Descrição','Forma','Valor'],m.map(x=>[new Date(x.date).toLocaleDateString('pt-BR'),esc(x.description),esc(x.method),`<span style="color:${x.value<0?'var(--red)':'var(--text)'}">${money(x.value)}</span>`]))}
function cashPage(){const pending=state.orders.filter(o=>!o.paid);return head('Caixa','Recebimentos e movimentações deste dispositivo.',state.cash.open?btn('Fechar caixa','closeCashModal()','wallet'):btn('Abrir caixa','openCashModal()','wallet',true))+`<div class="stats">${stat('Status do caixa',state.cash.open?'Aberto':'Fechado',state.cash.open?'Pronto para receber pagamentos':'Abra para iniciar o atendimento','wallet')}${stat('Valor inicial',money(state.cash.initial),'Fundo de abertura','money')}${stat('Saldo esperado',money(state.cash.open?balance():0),'Inclui todas as formas de pagamento','chart')}${stat('A receber',money(pending.reduce((s,o)=>s+o.total,0)),`${pending.length} ordens pendentes`,'orders')}</div><div class="panel"><div class="toolbar"><h2 style="margin:0">Ordens a receber</h2><div class="page-actions">${btn('Entrada / saída','movementModal()','plus')}${btn('Sangria',"movementModal('Sangria')",'wallet')}</div></div>${table(['OS / Veículo','Cliente','Etapa','Total',''],pending.map(o=>[`<b>#${o.id} · ${o.plate}</b>`,esc(o.client),badge(stages[o.stage]),money(o.total),btn('Receber',`receiveModal(${o.id})`,'wallet',true)]))}</div><div class="panel"><h2>Movimentações</h2>${movementTable(state.movements.slice().reverse())}</div><div class="panel"><h2>Histórico de fechamento</h2>${table(['Data','Esperado','Informado','Diferença'],state.cashHistory.map(h=>[new Date(h.date).toLocaleString('pt-BR'),money(h.expected),money(h.informed),badge(money(h.informed-h.expected),Math.abs(h.informed-h.expected)>.01?'warn':'good')]))}</div>`}
function openCashModal(){modal('Abertura de caixa',`<form onsubmit="openCash(event)">${field('Valor inicial em dinheiro (R$)','initial',0,'number','required min="0" step="0.01"')}<p class="muted">Registre o fundo disponível para troco.</p><div class="form-actions"><button class="primary">Abrir caixa</button></div></form>`)}
function openCash(e){e.preventDefault();state.cash={open:true,initial:Number(new FormData(e.target).get('initial')),opened:stamp()};persist();closeModal();render();toast('Caixa aberto.')}
function receiveModal(id){if(!state.cash.open){modal('Caixa fechado',`<p>Abra o caixa antes de receber esta ordem.</p><div class="form-actions">${btn('Abrir caixa','openCashModal()','wallet',true)}</div>`);return}const o=state.orders.find(o=>o.id===id);if(o.paid){toast('Ordem já recebida.');return}modal(`Receber OS #${id}`,`<p>${esc(o.client)} · <b>${o.plate}</b></p><div class="summary-line total"><span>Total</span><span>${money(o.total)}</span></div><form onsubmit="receive(event,${id})"><div class="form-grid" style="margin-top:20px">${selectField('Forma de pagamento','method',['Dinheiro','PIX','Débito','Crédito','Outros'].map(x=>[x,x]))}${field('Valor recebido (R$)','received',o.total,'number',`required min="${o.total}" step="0.01" oninput="document.getElementById('change').textContent=money(Math.max(0,Number(this.value)-${o.total}))"`)}</div><div class="summary-line"><span>Troco (dinheiro)</span><b id="change">R$ 0,00</b></div><div class="notice">Confirme o pagamento com o cliente. PIX e cartão são registrados manualmente; não há confirmação bancária automática.</div><div class="form-actions"><button class="primary">Confirmar recebimento</button></div></form>`)}
function receive(e,id){e.preventDefault();const o=state.orders.find(o=>o.id===id);if(o.paid)return;const fd=new FormData(e.target),v=Number(fd.get('received'));if(v<o.total)return;o.paid=true;o.paidAt=stamp();o.method=fd.get('method');state.movements.push({id:uid(),date:stamp(),type:'Recebimento',description:`OS #${id} · ${o.client}`,value:o.total,method:o.method,orderId:id});persist();closeModal();render();toast('Pagamento registrado. A entrega pode ser confirmada no pátio.')}
function movementModal(type='Saída'){if(!state.cash.open){toast('Abra o caixa para registrar movimentações.');return}modal(type==='Sangria'?'Registrar sangria':'Entrada ou saída manual',`<form onsubmit="saveMovement(event)"><div class="form-grid">${selectField('Tipo','type',type==='Sangria'?[['Sangria','Sangria']]:[['Entrada','Entrada'],['Saída','Saída']],type)}${field('Valor (R$)','value','','number','required min="0.01" step="0.01"')}${field('Descrição','description','','text','required')}${selectField('Forma','method',['Dinheiro','PIX','Débito','Crédito','Outros'].map(x=>[x,x]))}</div><div class="form-actions"><button class="primary">Registrar movimentação</button></div></form>`)}
function saveMovement(e){e.preventDefault();const x=Object.fromEntries(new FormData(e.target));state.movements.push({...x,id:uid(),date:stamp(),value:Number(x.value)*(x.type==='Entrada'?1:-1)});persist();closeModal();render();toast('Movimentação registrada.')}
function closeCashModal(){modal('Fechamento de caixa',`<p class="muted">Confira o total de todas as formas de pagamento.</p><div class="summary-line"><span>Valor esperado</span><b>${money(balance())}</b></div><form onsubmit="closeCash(event)">${field('Valor total informado (R$)','informed','','number',`required min="0" step="0.01" oninput="document.getElementById('difference').textContent=money(Number(this.value)-balance())"`)}<div class="summary-line"><span>Diferença</span><b id="difference">—</b></div><div class="form-actions"><button class="primary">Confirmar fechamento</button></div></form>`)}
function closeCash(e){e.preventDefault();state.cashHistory.push({date:stamp(),expected:balance(),informed:Number(new FormData(e.target).get('informed'))});state.cash.open=false;persist();closeModal();render();toast('Caixa fechado. Conferência salva no histórico.')}
let onlineAppointments=null,onlineAppointmentsLoading=false,onlineAppointmentsError='';
function currentSaasLicenseKey(){return(typeof operationalData!=='undefined'&&operationalData?.settings?.saasLicenseKey)||(typeof state!=='undefined'&&state.settings?.saasLicenseKey)||''}
function currentSaasSlug(){return(typeof operationalData!=='undefined'&&operationalData?.settings?.saasSlug)||(typeof state!=='undefined'&&state.settings?.saasSlug)||''}
async function loadOnlineAppointments(){
  const key=currentSaasLicenseKey();
  if(!key)return;
  onlineAppointmentsLoading=true;
  onlineAppointmentsError='';
  if(page==='agenda_online')render();
  try{
    const res=await fetch('../api_lavarapido_public.php?action=pending_for_license',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({license_key:key})
    });
    if(!res.ok)throw new Error(`Falha de comunicação (${res.status})`);
    const data=await res.json();
    if(data&&data.status==='success'&&Array.isArray(data.appointments)){
      onlineAppointments=data.appointments;
    }else{
      throw new Error((data&&data.message)||'Erro ao buscar agendamentos.');
    }
  }catch(err){
    onlineAppointmentsError=err.message||'Não foi possível consultar os agendamentos online.';
    onlineAppointments=[];
    toast('Não foi possível carregar os agendamentos online.');
  }finally{
    onlineAppointmentsLoading=false;
    if(page==='agenda_online')render();
  }
}
// Cria a OS real (operational-ui.js: operationalData/api(), não state/draft de
// app.js, que é sombra morta nesta build — ver memória
// lavarapido-operational-ui-shadows-appjs). newOrder() não tem mecanismo de
// pré-preenchimento, então em vez de navegar pra lá montamos a confirmação
// direto, do mesmo jeito que createOperationalOrder() faz.
async function convertAppointmentToOrder(id){
  const a=(onlineAppointments||[]).find(x=>String(x.id)===String(id));
  if(!a)return;
  if(typeof operationalData==='undefined'||!operationalData){toast('Aguarde o carregamento da operação e tente novamente.');return}
  const plateClean=(a.vehicle_plate||'').trim().toUpperCase();
  if(!plateClean){toast('Este agendamento não informou placa. Crie a OS manualmente em "Nova Ordem de Serviço".');return}

  const services=(operationalData.services||[]).filter(s=>s.active);
  let principalServiceId='';
  if(a.service_local_id!=null){
    const byId=services.find(s=>String(s.id)===String(a.service_local_id));
    if(byId)principalServiceId=byId.id;
  }
  if(!principalServiceId&&a.service_name){
    const sName=String(a.service_name).trim().toLowerCase();
    const exact=services.find(s=>s.name.trim().toLowerCase()===sName);
    if(exact)principalServiceId=exact.id;
    else{
      const partial=services.find(s=>s.name.toLowerCase().includes(sName)||sName.includes(s.name.toLowerCase()));
      if(partial)principalServiceId=partial.id;
    }
  }
  if(!principalServiceId){toast(`Não encontramos um serviço correspondente a "${a.service_name||''}". Cadastre-o em Serviços e tente novamente.`);return}

  // Atualiza o cache antes de procurar o cliente -- evita 409 "placa já
  // cadastrada" quando outra aba/estação criou o veículo depois do último load.
  try{await refreshOperationalData()}catch{}

  function findByPlate(){
    for(const c of(operationalData.customers||[])){
      const v=(c.vehicles||[]).find(x=>(x.plate||'').toUpperCase()===plateClean);
      if(v)return{customer:c,vehicle:v};
    }
    return null;
  }

  let customer=null,vehicle=null;
  const found=findByPlate();
  if(found){customer=found.customer;vehicle=found.vehicle}
  if(!customer){
    try{
      const res=await api('/api/operational/customers',{method:'POST',body:JSON.stringify({
        name:a.client_name||'Cliente agenda online',
        phone:a.client_phone||'',
        plate:plateClean,
        model:a.vehicle_model||''
      })});
      await refreshOperationalData();
      customer=operationalData.customers.find(c=>c.id===res.customer.id);
      vehicle=customer?.vehicles.find(v=>v.id===res.customer.vehicle.id);
    }catch(err){
      // Placa já existe (409) mas não estava no cache antes do refresh acima:
      // outra estação deve ter criado nesse intervalo. Tenta achar de novo
      // em vez de simplesmente abortar.
      await refreshOperationalData().catch(()=>{});
      const retry=findByPlate();
      if(retry){customer=retry.customer;vehicle=retry.vehicle}
      else{toast(err.message||'Não foi possível criar o cliente a partir do agendamento.');return}
    }
  }
  if(!customer||!vehicle){toast('Não foi possível localizar o cliente/veículo criado.');return}

  const service=services.find(s=>s.id===principalServiceId);
  const today=new Date().toLocaleDateString('sv-SE',{timeZone:'America/Sao_Paulo'});
  const duplicateToday=(operationalData.orders||[]).some(o=>o.vehicle?.plate===vehicle.plate&&o.paymentStatus!=='cancelled'&&String(o.enteredAt||'').slice(0,10)===today);
  const duplicateWarning=duplicateToday?`<p class="notice">${icon('alert')}Este veículo já tem uma OS registrada hoje. Confira em Ordens de Serviço antes de confirmar, pra não duplicar.</p>`:'';
  const payload={
    customerId:customer.id,vehicleId:vehicle.id,
    principalServiceId,additionalServiceIds:[],
    employeeId:'',discount:'0',
    note:[a.appointment_date?`Agendamento online: ${a.appointment_date}${a.appointment_time?' às '+a.appointment_time:''}`:''].filter(Boolean).join(' · '),
    checkin:{odometerKm:'',fuelLevel:'Não informado',keyCount:1,accessories:'',conditionNotes:''},
    sourceAppointmentId:a.id
  };
  operationalOrderConfirmation=payload;
  modal('Conferir entrada no pátio',`<div class="summary-list order-confirmation"><p><span><b>Cliente</b><br><small>${safeText(customer.name)}${customer.phone?` · ${safeText(customer.phone)}`:''}</small></span></p><p><span><b>Veículo</b><br><small>${safeText(vehicle.plate)} · ${safeText([vehicle.brand,vehicle.model,vehicle.color].filter(Boolean).join(' · '))||'Sem detalhes adicionais'}</small></span></p><p><span><b>Serviço</b><br><small>${safeText(service?.name||'')}</small></span></p><p class="total"><span>Total da OS</span><b>${operationalMoney(service?.price||0)}</b></p></div>${duplicateWarning}<p class="muted">Vindo do agendamento online. A ordem entrará em Aguardando no Pátio.</p><div class="form-actions"><button onclick="closeModal()">Cancelar</button><button class="primary" onclick="confirmOperationalOrder()">Criar OS e abrir pátio</button></div>`);
}
function onlineAgendaPage(){
  const licenseKey=currentSaasLicenseKey();
  if(!licenseKey){
    return head('Agenda Online','Agendamentos recebidos pela internet.')+`<div class="panel empty-state" style="text-align:center;padding:40px 20px;"><div style="font-size:32px;margin-bottom:12px">${icon('calendar')}</div><h2>Add-on SaaS não ativado</h2><p class="muted" style="max-width:500px;margin:8px auto 20px;">Para receber e gerenciar agendamentos de clientes pela internet, ative o add-on SaaS em Configurações.</p>${btn('Ir para Configurações',"route('config')",'settings',true)}</div>`;
  }
  if(onlineAppointments===null&&!onlineAppointmentsLoading&&!onlineAppointmentsError){
    setTimeout(loadOnlineAppointments,0);
  }
  let body='';
  if(onlineAppointmentsLoading){
    body=`<div class="panel"><div class="empty">Buscando agendamentos online pendentes…</div></div>`;
  }else if(onlineAppointmentsError){
    body=`<div class="panel"><p class="error">${esc(onlineAppointmentsError)}</p><div class="form-actions">${btn('Tentar novamente','loadOnlineAppointments()','arrow',true)}</div></div>`;
  }else{
    const list=onlineAppointments||[];
    const rows=list.map(a=>{
      const plate=esc((a.vehicle_plate||'').toUpperCase());
      const model=esc(a.vehicle_model||'');
      const vehicleCol=`<b>${plate||'—'}</b>${model?`<br><small class="muted">${model}</small>`:''}`;
      const clientName=esc(a.client_name||'—');
      const clientPhone=esc(a.client_phone||'');
      const clientCol=`<b>${clientName}</b>${clientPhone?`<br><small class="muted">${clientPhone}</small>`:''}`;
      const serviceName=esc(a.service_name||'—');
      const servicePrice=a.price?money(a.price):'';
      const serviceCol=`<b>${serviceName}</b>${servicePrice?`<br><small class="muted">${servicePrice}</small>`:''}`;
      let dateDisplay=esc(a.appointment_date||'—');
      if(a.appointment_date&&a.appointment_date.includes('-')){
        const p=a.appointment_date.split('-');
        if(p.length===3)dateDisplay=`${p[2]}/${p[1]}/${p[0]}`;
      }
      const timeDisplay=a.appointment_time?` às ${esc(a.appointment_time)}`:'';
      const dateTimeCol=`${dateDisplay}${timeDisplay}`;
      const actionCol=btn('Criar OS',`convertAppointmentToOrder('${esc(String(a.id))}')`,'plus',true);
      return [vehicleCol,clientCol,serviceCol,dateTimeCol,actionCol];
    });
    body=`<div class="stats">${stat('Agendamentos pendentes',list.length,'Recebidos pela internet','calendar')}</div><div class="panel"><div class="toolbar" style="margin-bottom:16px"><h2 style="margin:0">Agendamentos pendentes</h2>${btn('Atualizar','loadOnlineAppointments()','arrow')}</div>${table(['Veículo/Placa','Cliente','Serviço','Data/Hora',''],rows)}</div>`;
  }
  const saasSlug=currentSaasSlug();
  const headActions=saasSlug?`<a class="small-button" href="agendar/?s=${encodeURIComponent(saasSlug)}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:6px">${icon('calendar')}Ver página pública</a>`:'';
  return head('Agenda Online','Agendamentos recebidos pela internet.',headActions)+body;
}
function clientsPage(){return head('Clientes e Veículos','Dados de contato e histórico de cada veículo.',btn('Novo cliente',"editEntity('client')",'plus',true))+`<div class="toolbar">${search('Buscar nome, telefone ou placa…')}</div><div class="panel" id="results">${clientsTable()}</div>`}
function clientsTable(){return table(['Cliente','Telefone','Veículos','Atendimentos','Total gasto',''],state.clients.filter(c=>JSON.stringify(c).toLowerCase().includes(query.toLowerCase())).map(c=>{const os=state.orders.filter(o=>o.clientId===c.id);return [`<b>${esc(c.name)}</b>`,esc(c.phone),c.vehicles.map(v=>`<span class="badge">${esc(v.plate)}</span>`).join(' '),os.length,money(os.filter(o=>o.paid).reduce((s,o)=>s+o.total,0)),btn('Perfil',`clientDetail(${c.id})`,'arrow')]}))}
function clientDetail(id){const c=state.clients.find(c=>c.id===id),os=state.orders.filter(o=>o.clientId===id);modal(esc(c.name),`<p class="muted">${esc(c.phone)}</p><div class="summary-line"><span>Total gasto</span><b>${money(os.filter(o=>o.paid).reduce((s,o)=>s+o.total,0))}</b></div><div class="summary-line"><span>Atendimentos / última visita</span><b>${os.length} · ${os.length?new Date(os[os.length-1].entered).toLocaleDateString('pt-BR'):'Sem visitas'}</b></div><p>${esc(c.notes||'Sem observações.')}</p><h2>Veículos vinculados</h2>${c.vehicles.map((v,i)=>`<div class="activity"><div><b>${esc(v.plate)}</b><p class="muted">${esc(v.brand)} ${esc(v.model)} · ${esc(v.color)} · ${esc(v.year)}</p></div>${btn('Histórico',`vehicleDetail(${id},${i})`,'arrow')}</div>`).join('')}<div class="form-actions">${btn('Adicionar veículo',`addVehicle(${id})`,'plus')}${btn('Editar cliente',`editEntity('client',${id})`,'user')}</div><h2 style="margin-top:25px">Histórico de ordens</h2>${table(['Ordem','Serviço','Total'],os.map(o=>[`<button onclick="orderDetail(${o.id})">#${o.id}</button>`,esc(o.service),money(o.total)]))}`)}
function vehicleDetail(id,i){const c=state.clients.find(c=>c.id===id),v=c.vehicles[i],os=state.orders.filter(o=>o.plate===v.plate);modal(`Veículo ${esc(v.plate)}`,`<p>${esc(v.brand)} ${esc(v.model)} · ${esc(v.color)} · ${esc(v.year)}</p><p class="muted">Proprietário: ${esc(c.name)} · ${os.length} visitas registradas</p><div class="notice">Observações e avarias: ${esc(v.notes||'Nenhuma registrada.')}</div>${table(['Data','Serviço','Observações'],os.map(o=>[new Date(o.entered).toLocaleDateString('pt-BR'),esc(o.service),esc(o.note||'—')]))}`)}
function addVehicle(id){modal('Adicionar veículo',`<form onsubmit="saveVehicle(event,${id})"><div class="form-grid">${field('Placa','plate','','text','required pattern="[A-Za-z]{3}[0-9][A-Za-z0-9][0-9]{2}" maxlength="7"')}${field('Marca','brand','','text','required')}${field('Modelo','model','','text','required')}${field('Cor','color','','text','required')}${field('Ano','year','','number','min="1950" max="2030"')}${field('Observações / avarias','notes')}</div><div class="form-actions"><button class="primary">Salvar veículo</button></div></form>`)}
function saveVehicle(e,id){e.preventDefault();const v=Object.fromEntries(new FormData(e.target));v.plate=v.plate.toUpperCase();if(state.clients.some(c=>c.vehicles.some(x=>x.plate===v.plate))){toast('Esta placa já está cadastrada.');return}state.clients.find(c=>c.id===id).vehicles.push(v);persist();clientDetail(id);toast('Veículo vinculado.')}
function servicesPage(){return head('Serviços e Combos','Preços, duração e comissões dos serviços.',btn('Novo serviço',"editEntity('service')",'plus',true))+`<div class="panel">${table(['Serviço','Categoria','Duração','Preço','Comissão','Status',''],state.services.map(s=>[`<b>${esc(s.name)}</b>`,esc(s.category),`${s.duration} min`,money(s.price),`${s.commission}%`,badge(s.active?'Ativo':'Inativo',s.active?'good':''),btn('Editar',`editEntity('service',${s.id})`,'settings')]))}</div>`}
function teamPage(){return head('Equipe','Responsáveis pelos atendimentos e comissões.',btn('Novo funcionário',"editEntity('team')",'plus',true))+`<div class="tiles">${state.team.map(e=>`<div class="tile"><div class="intro-row"><span class="avatar">${initials(e.name)}</span><div><h3>${esc(e.name)}</h3><p style="margin:4px 0">${esc(e.role)}</p></div></div>${badge(e.active?'Ativo':'Inativo',e.active?'good':'')}<p>${esc(e.phone)}</p><div class="summary-line"><span>Serviços realizados</span><b>${state.orders.filter(o=>o.employee===e.name&&o.stage===4).length}</b></div><div class="summary-line"><span>Comissão padrão</span><b>${e.commission}%</b></div><div class="form-actions">${btn('Editar',`editEntity('team',${e.id})`,'settings')}</div></div>`).join('')}</div>`}
function stockPage(){return head('Produtos e Estoque','Controle simples de produtos e materiais de consumo.',btn('Novo produto',"editEntity('product')",'plus',true))+`<div class="stats">${stat('Produtos cadastrados',state.products.length,'Itens de limpeza, consumo e balcão','box')}${stat('Estoque baixo',state.products.filter(p=>p.qty<=p.min).length,'Itens que precisam de reposição','alert')}${stat('Movimentações',state.stockHistory.length,'Entradas, saídas e ajustes','orders')}${stat('Controle','Local','Sem integrações externas','shield')}</div><div class="panel">${table(['Produto','Categoria','Atual','Mínimo','Status',''],state.products.map(p=>[`<b>${esc(p.name)}</b>`,esc(p.category),`${p.qty} ${esc(p.unit)}`,`${p.min} ${esc(p.unit)}`,badge(p.qty<=p.min?'Estoque baixo':'Regular',p.qty<=p.min?'warn':'good'),`${btn('Movimentar',`stockModal(${p.id})`,'plus')} ${btn('Editar',`editEntity('product',${p.id})`,'settings')}`]))}</div><div class="panel"><h2>Histórico de estoque</h2>${table(['Data','Produto','Tipo','Quantidade','Motivo'],state.stockHistory.slice().reverse().map(h=>[new Date(h.date).toLocaleString('pt-BR'),esc(h.product),esc(h.type),h.qty,esc(h.reason)]))}</div>`}
function stockModal(id){const p=state.products.find(p=>p.id===id);modal(`Movimentar ${esc(p.name)}`,`<p class="muted">Estoque atual: ${p.qty} ${esc(p.unit)}</p><form onsubmit="stockMove(event,${id})"><div class="form-grid">${selectField('Tipo de movimentação','type',['Entrada','Saída','Perda','Ajuste'].map(x=>[x,x]))}${field('Quantidade (ajuste = saldo final)','qty','','number','required min="0" step="0.01"')}${field('Motivo','reason','','text','required')}</div><p id="stock-error" class="error"></p><div class="form-actions"><button class="primary">Salvar movimentação</button></div></form>`)}
function stockMove(e,id){e.preventDefault();const x=Object.fromEntries(new FormData(e.target)),p=state.products.find(p=>p.id===id),n=Number(x.qty),next=x.type==='Ajuste'?n:p.qty+(x.type==='Entrada'?n:-n);if(next<0){$('#stock-error').textContent='Quantidade superior ao estoque disponível.';return}p.qty=next;state.stockHistory.push({...x,product:p.name,date:stamp()});persist();closeModal();render();toast('Estoque atualizado.')}
function editEntity(type,id){const collections={client:'clients',service:'services',team:'team',product:'products'},x=state[collections[type]].find(x=>x.id===id)||{};let fields=type==='client'?field('Nome','name',x.name,'text','required')+field('Telefone','phone',x.phone,'tel','required')+field('Observações','notes',x.notes):type==='service'?field('Nome','name',x.name,'text','required')+selectField('Categoria','category',['Principal','Adicional','Combo'].map(x=>[x,x]),x.category)+field('Preço (R$)','price',x.price,'number','required min="0" step="0.01"')+field('Duração (min)','duration',x.duration,'number','required min="1"')+field('Comissão (%)','commission',x.commission||0,'number','min="0" max="100" step="0.1"'):type==='team'?field('Nome','name',x.name,'text','required')+field('Telefone','phone',x.phone,'tel','required')+field('Função','role',x.role,'text','required')+field('Comissão padrão (%)','commission',x.commission||0,'number','min="0" max="100" step="0.1"'):field('Nome','name',x.name,'text','required')+selectField('Categoria','category',['Limpeza','Consumo','Balcão'].map(x=>[x,x]),x.category)+field('Unidade','unit',x.unit||'un.','text','required')+field('Estoque atual','qty',x.qty||0,'number','min="0" step="0.01" required')+field('Estoque mínimo','min',x.min||0,'number','min="0" step="0.01" required');if(['service','team'].includes(type))fields+=selectField('Status','active',[['true','Ativo'],['false','Inativo']],x.active===false?'false':'true');modal(`${id?'Editar':'Cadastrar'} ${ {client:'cliente',service:'serviço',team:'funcionário',product:'produto'}[type]}`,`<form onsubmit="saveEntity(event,'${type}',${id||0})"><div class="form-grid">${fields}</div><div class="form-actions"><button class="primary">Salvar cadastro</button></div></form>`)}
function saveEntity(e,type,id){e.preventDefault();const x=Object.fromEntries(new FormData(e.target));for(const k of ['price','duration','commission','qty','min'])if(k in x)x[k]=Number(x[k]);if('active'in x)x.active=x.active==='true';const arr=state[{client:'clients',service:'services',team:'team',product:'products'}[type]];if(id)Object.assign(arr.find(x=>x.id===id),x);else arr.push({...x,id:uid(),...(type==='client'?{vehicles:[]}: {})});persist();closeModal();render();toast('Cadastro salvo neste dispositivo.')}
function periodControls(){return `<div class="report-controls">${field('De','from',periodFrom,'date')}${field('Até','to',periodTo,'date')}${btn('Aplicar período','applyPeriod()','filter')}${btn('Imprimir','window.print()','orders')}${btn('Exportar CSV','exportReport()','download')}</div>`}
function applyPeriod(){periodFrom=$('#from').value;periodTo=$('#to').value;if(periodFrom&&periodTo&&periodFrom>periodTo){toast('A data inicial deve ser anterior à final.');return}render()}
function inPeriod(date){const d=new Date(date);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return(!periodFrom||iso>=periodFrom)&&(!periodTo||iso<=periodTo)}
function financePage(){const m=state.movements.filter(m=>inPeriod(m.date)),income=m.filter(m=>m.value>0).reduce((s,m)=>s+m.value,0),expense=-m.filter(m=>m.value<0).reduce((s,m)=>s+m.value,0);return head('Financeiro','Receitas e despesas registradas manualmente.')+periodControls()+`<div class="stats">${stat('Receitas',money(income),'Entradas no período','money')}${stat('Despesas e sangrias',money(expense),'Saídas no período','wallet')}${stat('Saldo do período',money(income-expense),'Receitas menos saídas','chart')}${stat('Movimentações',m.length,'Registros locais','orders')}</div><div class="panel"><h2>Movimentações do período</h2>${movementTable(m.slice().reverse())}</div>`}
function commissionRows(){return state.team.map(e=>{const os=state.orders.filter(o=>o.employee===e.name&&o.stage===4&&inPeriod(o.delivered||o.entered));const total=os.reduce((sum,o)=>{const svc=state.services.find(s=>s.name===o.service);return sum+o.total*Number(svc?.commission??e.commission)/100},0);return[e,os,total]})}
function commissionsPage(){const rows=commissionRows();return head('Comissões','Comissões estimadas sobre serviços entregues.')+periodControls()+`<div class="stats">${stat('Total de comissões',money(rows.reduce((s,r)=>s+r[2],0)),'No período selecionado','money')}${stat('Equipe',state.team.length,'Funcionários cadastrados','users')}${stat('Serviços entregues',rows.reduce((s,r)=>s+r[1].length,0),'Base do cálculo','check')}${stat('Critério','Por serviço','Percentual do serviço ou do funcionário','chart')}</div><div class="panel">${table(['Funcionário','Serviços','Receita atendida','Comissão estimada'],rows.map(([e,os,total])=>[esc(e.name),os.length,money(os.reduce((s,o)=>s+o.total,0)),money(total)]))}<div class="notice">O percentual configurado no serviço tem prioridade sobre o percentual padrão da equipe. Esta tela estima comissões; não realiza pagamento nem folha salarial.</div></div>`}
function serviceTotals(os=state.orders){const map={};os.forEach(o=>map[o.service]=(map[o.service]||0)+1);return Object.entries(map).sort((a,b)=>b[1]-a[1])}
function reportsPage(){const os=state.orders.filter(o=>inPeriod(o.entered)),m=state.movements.filter(m=>inPeriod(m.date)),sum=m.filter(x=>x.value>0).reduce((s,x)=>s+x.value,0),exp=-m.filter(x=>x.value<0).reduce((s,x)=>s+x.value,0),del=os.filter(o=>o.stage===4),paid=os.filter(o=>o.paid);return head('Relatórios','Indicadores da operação, com filtros por período.')+periodControls()+`<div class="stats">${stat('Faturamento',money(sum),'Receitas registradas','money')}${stat('Veículos atendidos',os.length,'Ordens abertas no período','car')}${stat('Ticket médio',money(paid.reduce((s,o)=>s+o.total,0)/(paid.length||1)),'Sobre ordens recebidas','chart')}${stat('Tempo médio',`${Math.round(del.reduce((s,o)=>s+elapsed(o),0)/(del.length||1))} min`,'Da entrada à entrega','clock')}</div><div class="two-grid"><section class="panel"><h2>Serviços mais vendidos</h2>${table(['Serviço','Quantidade','Valor de ordens'],serviceTotals(os).map(([s,n])=>[esc(s),n,money(os.filter(o=>o.service===s).reduce((sum,o)=>sum+o.total,0))]))}</section><section class="panel"><h2>Formas de pagamento</h2>${table(['Forma','Total recebido'],['Dinheiro','PIX','Débito','Crédito','Outros'].map(f=>[f,money(m.filter(x=>x.method===f&&x.value>0).reduce((s,x)=>s+x.value,0))]))}</section><section class="panel"><h2>Resultado financeiro</h2>${[['Receitas',sum],['Despesas e sangrias',exp],['Resultado',sum-exp]].map(([s,n])=>`<div class="summary-line"><span>${s}</span><b>${money(n)}</b></div>`).join('')}</section><section class="panel"><h2>Produtividade e comissões</h2>${table(['Funcionário','Entregas','Comissão'],commissionRows().map(([e,os,total])=>[esc(e.name),os.length,money(total)]))}</section><section class="panel"><h2>Clientes recorrentes</h2>${table(['Cliente','Visitas no período'],state.clients.map(c=>[c,os.filter(o=>o.clientId===c.id).length]).filter(x=>x[1]>1).sort((a,b)=>b[1]-a[1]).map(([c,n])=>[esc(c.name),n]))}</section></div>`}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportReport(){const rows=[['OS','Data','Cliente','Placa','Serviço','Etapa','Valor','Pagamento'],...state.orders.filter(o=>inPeriod(o.entered)).map(o=>[o.id,new Date(o.entered).toLocaleDateString('pt-BR'),o.client,o.plate,o.service,stages[o.stage],o.total,o.paid?o.method:'Pendente'])];download(`relatorio-${Date.now()}.csv`,'\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Relatório exportado em CSV.')}
function notificationsPage(){const lateOs=state.orders.filter(late),low=state.products.filter(p=>p.qty<=p.min);return head('Notificações','Avisos operacionais gerados neste dispositivo.')+`<div class="panel">${[...lateOs.map(o=>`<div class="activity"><div>${badge('Atraso','warn')} <b>${o.plate}</b><p class="muted">OS #${o.id} ultrapassou a previsão de atendimento.</p></div>${btn('Ver OS',`orderDetail(${o.id})`,'arrow')}</div>`),...low.map(p=>`<div class="activity"><div>${badge('Estoque baixo','warn')} <b>${esc(p.name)}</b><p class="muted">${p.qty} ${p.unit} disponíveis · mínimo ${p.min}</p></div>${btn('Estoque',"route('estoque')",'box')}</div>`),`<div class="activity"><div>${badge('Backup','info')} <b>Proteja seus dados locais</b><p class="muted">${state.backup?'Último backup: '+new Date(state.backup).toLocaleString('pt-BR'):'Nenhum backup gerado neste dispositivo.'}</p></div>${btn('Gerar backup',"route('backup')",'backup')}</div>`].join('')}</div>`}
function settingsPage(){const s=state.settings;const saasSlug=s.saasSlug||'';const saasLicenseKey=s.saasLicenseKey||'';return head('Configurações','Preferências da unidade e da operação.')+`<form onsubmit="saveSettings(event)"><div class="two-grid"><div><section class="panel"><h2>Dados do lava-rápido</h2><div class="form-grid">${field('Nome da unidade','name',s.name,'text','required')}${field('CNPJ ou CPF','document',s.document)}${field('Telefone','phone',s.phone,'tel')}${field('Endereço','address',s.address)}${field('Horário de funcionamento','hours',s.hours)}<div><label for="logo">Logotipo (PNG ou JPG)</label><input id="logo" type="file" accept="image/png,image/jpeg" onchange="uploadLogo(this)">${s.logo?`<img src="${s.logo}" style="max-width:100px;max-height:60px;margin-top:10px" alt="Logo da unidade">`:''}</div></div></section><section class="panel"><h2>Preferências operacionais</h2><div class="form-grid">${field('Próximo número de OS','next',s.next,'number',`required min="${Math.max(...state.orders.map(o=>o.id),0)+1}"`)}${field('Tolerância de atraso (min)','tolerance',s.tolerance,'number','required min="0"')}${selectField('Moeda','currency',[['BRL','Real brasileiro (R$)']],s.currency)}${field('Formas de pagamento','payments',s.payments)}</div></section></div><div><section class="panel"><h2>Add-on SaaS: Agenda Online</h2><p class="muted">Opcional. Gerado pelo suporte ao evoluir sua licença vitalícia para o add-on SaaS.</p><div class="form-grid">${field('Chave da licença SaaS (saasLicenseKey)','saasLicenseKey',saasLicenseKey)}${field('Slug da agenda (saasSlug)','saasSlug',saasSlug)}</div><div style="margin-top:12px">${saasSlug?`<a class="small-button" href="../agendar/?slug=${encodeURIComponent(saasSlug)}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:6px">${icon('calendar')}Ver página pública de agendamento</a>`:`<button type="button" class="small-button" disabled>${icon('calendar')}Ver página pública de agendamento</button>`}</div></section><section class="panel"><h2>Aparência e impressão</h2><div class="form-grid">${selectField('Tema','theme',[['dark','Escuro'],['light','Claro']],s.theme)}${selectField('Formato de impressão','print',[['80 mm','Bobina 80 mm'],['A4','Papel A4']],s.print)}</div><div class="notice">A impressão utiliza a janela de impressão do dispositivo. Configure o papel e a impressora nessa janela.</div></section><section class="panel"><h2>Licença do produto</h2><p class="muted">Frontend de demonstração · Unidade única</p>${badge('Licenciamento demonstrativo','info')}<p>Licença vitalícia · Pagamento único de R$ 299,90.</p>${btn('Ativação de licença',"route('licenca')",'shield')}</section><button class="primary" type="submit">${icon('check')}Salvar configurações</button></div></div></form>`}
function saveSettings(e){e.preventDefault();const s=Object.fromEntries(new FormData(e.target));s.next=Number(s.next);s.tolerance=Number(s.tolerance);Object.assign(state.settings,s);persist();render();toast('Configurações salvas.')}
function uploadLogo(input){const f=input.files[0];if(!f)return;if(f.size>500000){toast('Use um arquivo de até 500 KB.');return}const reader=new FileReader();reader.onload=()=>{state.settings.logo=reader.result;persist();toast('Logotipo salvo.')};reader.readAsDataURL(f)}
function backupPage(){return head('Backup e Restauração','Uma cópia segura dos dados da sua operação.')+`<div class="notice">${icon('shield')}Os dados ficam somente neste navegador e dispositivo. Limpar os dados do navegador pode removê-los. Mantenha cópias externas em um pendrive ou outro local seguro.</div><div class="two-grid"><section class="panel"><div class="intro-row"><span class="avatar">${icon('download')}</span><div><h2 style="margin:0">Gerar backup completo</h2><p class="muted" style="margin:5px 0">Exportação manual em arquivo JSON</p></div></div><p>Inclui clientes, veículos, ordens, serviços, equipe, estoque, caixa e configurações.</p><div class="summary-line"><span>Último backup</span><b>${state.backup?new Date(state.backup).toLocaleString('pt-BR'):'Ainda não gerado'}</b></div><div class="form-actions">${btn('Baixar backup JSON','backupDownload()','download',true)}</div></section><section class="panel"><h2>Restaurar dados</h2><p class="muted">Selecione um backup gerado por este sistema. A restauração substituirá todas as informações atuais.</p><label for="restore">Arquivo de backup (.json)</label><input id="restore" type="file" accept=".json,application/json" onchange="prepareRestore(this)"><p id="restore-error" class="error"></p><div class="notice">Gere um backup dos dados atuais antes de restaurar outro arquivo.</div></section></div>`}
function backupDownload(){state.backup=stamp();persist();download(`gestao-lava-rapido-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2),'application/json');render();toast('Backup gerado. Guarde o arquivo em um local seguro.')}
let pendingRestore;function prepareRestore(input){const f=input.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);validateBackup(x);pendingRestore=x;confirmAction('Substituir todos os dados?',`Este backup contém ${x.orders.length} ordens e ${x.clients.length} clientes. Os dados atuais serão substituídos.`,"restoreNow()")}catch(e){$('#restore-error').textContent='Arquivo inválido ou incompatível. Nenhum dado foi alterado.'}};r.readAsText(f)}
function validateBackup(x){if(x.version!==1||!x.settings||typeof x.settings.name!=='string'||!x.cash||!Number.isFinite(x.cash.initial))throw Error();for(const k of ['orders','clients','services','team','products','movements','stockHistory','cashHistory'])if(!Array.isArray(x[k]))throw Error();if(x.orders.some(o=>typeof o.plate!=='string'||typeof o.client!=='string'||typeof o.service!=='string'||typeof o.employee!=='string'||!Number.isFinite(o.total)||!Number.isInteger(o.stage)||o.stage<0||o.stage>4||isNaN(new Date(o.entered))))throw Error();if(x.clients.some(c=>typeof c.name!=='string'||!Array.isArray(c.vehicles)))throw Error();if(x.services.some(s=>typeof s.name!=='string'||!Number.isFinite(s.price)||!Number.isFinite(s.duration)))throw Error();if(x.products.some(p=>typeof p.name!=='string'||!Number.isFinite(p.qty)||!Number.isFinite(p.min)))throw Error();if(x.team.some(e=>typeof e.name!=='string'))throw Error();if(x.movements.some(m=>typeof m.description!=='string'||!Number.isFinite(m.value)))throw Error()}
function restoreNow(){state=pendingRestore;pendingRestore=null;persist();closeModal();render();toast('Backup restaurado neste dispositivo.')}
function licensePage(){return head('Ativação de licença','Interface de ativação para instalação standalone.')+`<div class="two-grid"><section class="panel"><h2>Ativar licença vitalícia</h2><div class="notice">Modo de demonstração. Não há servidor de licenças conectado. Utilize uma chave fictícia no formato DEMO-XXXX-XXXX para explorar os estados da interface.</div><form onsubmit="demoLicense(event)"><div class="form-grid">${field('E-mail da compra','email','','email','required')}${field('Chave de licença fictícia','key','','text','required placeholder="DEMO-XXXX-XXXX"')}${field('Identificação demonstrativa do dispositivo','device','LOCAL-DEMO-001','text','readonly')}</div><p id="license-message" class="error"></p><div class="form-actions"><button class="primary">Ativar licença</button></div></form></section><section class="panel"><h2>Informações da licença</h2><p>Licença vitalícia · R$ 299,90 · Pagamento único.</p><p class="muted">Uma unidade, dados locais e sem mensalidade. A verificação de licença real deverá ser implementada na versão instalada.</p>${badge(state.license?'Estado demonstrativo: ativa':'Demonstração sem ativação','info')}<div class="form-actions">${btn('Ver estado bloqueado',"document.getElementById('license-message').textContent='Demonstração: licença bloqueada. Verifique os dados da compra com o suporte.'",'shield')}</div></section></div>`}
function demoLicense(e){e.preventDefault();const fd=new FormData(e.target);if(!/^DEMO-[A-Z0-9]{4}-[A-Z0-9]{4}$/.test(fd.get('key'))){$('#license-message').textContent='Formato inválido. Use DEMO-XXXX-XXXX (somente dados fictícios).';return}state.license={demo:true,date:stamp()};persist();render();toast('Estado de licença ativa demonstrado. Nenhuma licença real foi validada.')}
function manualPage(){return head('Manual de Uso','Orientações rápidas para a rotina do lava-rápido.')+`<div class="panel manual">${[['1. Como iniciar o dia','Abra a tela Caixa, selecione Abrir caixa e informe o valor inicial disponível para troco.'],['2. Como abrir uma ordem','Toque em Nova OS. Pesquise o cliente por nome, telefone ou placa. Preencha o veículo, selecione serviços e responsável, registre as avarias e confira o resumo antes de confirmar.'],['3. Como operar o pátio','Use Avançar etapa no card do veículo. O fluxo é Aguardando → Em lavagem → Em acabamento → Pronto → Entregue. No celular, selecione a etapa acima dos cards.'],['4. Como receber e entregar','Na tela Caixa ou nos detalhes da OS, selecione Receber. Registre manualmente a forma de pagamento e confira o recebimento. Depois confirme a entrega no pátio.'],['5. Como fechar o caixa','Confira o valor de todas as formas de pagamento, selecione Fechar caixa e informe o total contado. A diferença e o histórico ficam registrados.'],['6. Como controlar o estoque','Abra Produtos e Estoque e selecione Movimentar. Use Entrada para reposições, Saída para consumo, Perda para descartes ou Ajuste para informar o saldo final após contagem.'],['7. Como proteger os dados','Gere um backup JSON em Backup e Restauração. Guarde cópias externas regularmente. Restaurar substitui os dados após sua confirmação.'],['8. Funcionamento offline e demonstração','Esta interface usa dados fictícios armazenados no navegador. O cache offline será preparado se o navegador permitir o service worker; a primeira visita requer internet. O instalador standalone e a ativação real não fazem parte deste frontend.']].map(([t,p],i)=>`<details ${i===0?'open':''}><summary>${t}</summary><p>${p}</p></details>`).join('')}</div>`}
function evolutionPage(){return head('Central de Evolução','Possibilidades para versões futuras. Nenhum recurso abaixo está disponível.')+`<div class="tiles">${[['Sincronização em nuvem','Cópias e sincronização remotas.'],['Multiunidade','Acompanhamento de mais de uma unidade.'],['Dispositivos sincronizados','Operação compartilhada entre dispositivos.'],['Agendamento online','Reservas feitas pelo cliente.'],['Portal do cliente','Consulta de histórico pelo cliente.'],['Aplicativo para funcionários','Experiência separada para a equipe.'],['WhatsApp automático','Envio integrado de avisos.'],['Reconhecimento de placas e RFID','Identificação automática de veículos.'],['Pagamentos recorrentes','Cobranças online recorrentes.'],['Inteligência artificial','Análises e apoio automatizados.']].map(([t,p])=>`<div class="tile">${badge('Em breve')}<h3 style="margin-top:17px">${t}</h3><p>${p}</p><small>Recurso futuro · indisponível nesta versão</small></div>`).join('')}</div>`}
function morePage(){return head('Mais opções','Todos os módulos do sistema.')+`<div class="group-links">${nav.flatMap(x=>x[1]).map(([id,t,ic])=>`<a href="#${id}">${icon(ic)}${t}</a>`).join('')}</div>`}
window.addEventListener('online',()=>{render();toast('Conexão disponível.')});window.addEventListener('offline',()=>render());document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#search')?.focus()}});$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
